import { motion } from "framer-motion";
import { ArrowRight, Lightbulb, Rocket, Sparkles, WandSparkles } from "lucide-react";
import { Link } from "react-router-dom";
import { AppShell } from "@/components/AppShell";
import { AnimatedNumber } from "@/components/AnimatedNumber";
import { DemoFlow } from "@/components/DemoFlow";
import { GlassCard } from "@/components/GlassCard";
import { useToast } from "@/components/Toast";
import { useWorkspaceStore } from "@/hooks/useWorkspaceStore";

const featureCards = [
  {
    title: "技术",
    desc: "从 PRD、架构到页面、测试和预览，形成完整证据链。",
    Icon: Rocket,
  },
  {
    title: "产品",
    desc: "从零散问答升级为真正服务单人开发者的闭环工具。",
    Icon: Lightbulb,
  },
  {
    title: "人文",
    desc: "用成长反馈与模拟问答缓解独立创作的孤独感。",
    Icon: Sparkles,
  },
];

export default function Home() {
  const { input, snapshot, updateInput, regenerate } = useWorkspaceStore();
  const { notify } = useToast();

  const totalTasks = snapshot.modules.reduce((sum, m) => sum + m.tasks.length, 0);
  const completedTasks = snapshot.modules.reduce(
    (sum, m) => sum + m.tasks.filter((t) => t.status === "已完成").length,
    0,
  );

  const handleRegenerate = () => {
    regenerate();
    notify("作品蓝图已重新生成");
  };

  return (
    <AppShell
      eyebrow="独立参赛作品生成器"
      title="让 TRAE 不只生成代码，而是帮你做成一份完整的比赛作品"
      actions={
        <div className="grid gap-4 lg:grid-cols-[1.25fr_0.75fr]">
          <GlassCard className="overflow-hidden" eyebrow="一句话价值主张" title={snapshot.profile.valueProposition}>
            <div className="grid gap-4 lg:grid-cols-[0.7fr_1.3fr]">
              <div className="space-y-3">
                <p className="text-sm leading-6 text-slate-300">{snapshot.profile.painPoint}</p>
                <div className="inline-flex items-center gap-2 rounded-full border border-cyan-300/20 bg-cyan-300/10 px-3 py-2 text-xs text-cyan-100">
                  <Sparkles className="h-3.5 w-3.5" />
                  Slogan：{snapshot.profile.slogan}
                </div>
              </div>
              <div className="grid gap-3 sm:grid-cols-2">
                {snapshot.profile.highlights.map((item, index) => (
                  <motion.div
                    key={item}
                    initial={{ opacity: 0, y: 16 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: index * 0.08 }}
                    className="rounded-3xl border border-white/10 bg-slate-950/35 p-4"
                  >
                    <p className="text-xs uppercase tracking-[0.24em] text-slate-500">核心亮点 {index + 1}</p>
                    <p className="mt-2 text-sm leading-6 text-slate-200">{item}</p>
                  </motion.div>
                ))}
              </div>
            </div>
          </GlassCard>
          <GlassCard eyebrow="操作指引" title="先定义作品，再一键进入工作台">
            <div className="space-y-3 text-sm leading-6 text-slate-300">
              <p>1. 输入作品名称、目标用户和核心痛点。</p>
              <p>2. 自动生成四大模块、关键材料与展示内容。</p>
              <p>3. 进入工作台查看完整闭环，再切换到成果展台整理展示资料。</p>
            </div>
            <div className="mt-5 flex flex-wrap gap-3">
              <Link
                to="/workspace"
                className="inline-flex items-center gap-2 rounded-full bg-white px-4 py-2 text-sm font-medium text-slate-950 transition hover:bg-cyan-200"
              >
                进入创作工作台
                <ArrowRight className="h-4 w-4" />
              </Link>
              <Link
                to="/showcase"
                className="inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/5 px-4 py-2 text-sm text-white transition hover:border-cyan-300/40"
              >
                查看成果展台
              </Link>
              <Link
                to="/defense"
                className="inline-flex items-center gap-2 rounded-full border border-emerald-300/25 bg-emerald-300/10 px-4 py-2 text-sm text-emerald-50 transition hover:border-emerald-300/40"
              >
                进入展示模式
              </Link>
            </div>
          </GlassCard>
        </div>
      }
    >
      <div className="space-y-6">
        {/* 实时数据统计条 */}
        <motion.div
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"
        >
          {[
            { label: "任务推进", value: completedTasks, suffix: ` / ${totalTasks}`, hint: "已完成" },
            { label: "过程证据", value: snapshot.evidence.length, suffix: " 条", hint: "TRAE 使用留痕" },
            { label: "提示词记录", value: snapshot.prompts.length, suffix: " 条", hint: "可追溯" },
            { label: "导出材料", value: snapshot.documents.length, suffix: " 份", hint: "一键交付" },
          ].map((stat, index) => (
            <div
              key={stat.label}
              className="relative overflow-hidden rounded-3xl border border-white/10 bg-slate-950/40 p-5"
            >
              <div className="absolute -right-6 -top-6 h-20 w-20 rounded-full bg-cyan-400/10 blur-2xl" />
              <p className="text-[10px] uppercase tracking-[0.24em] text-slate-500">{stat.label}</p>
              <p className="mt-3 text-3xl font-bold text-white">
                <AnimatedNumber value={stat.value} />
                <span className="text-base font-medium text-slate-400">{stat.suffix}</span>
              </p>
              <p className="mt-1 text-xs text-emerald-300/80">{stat.hint}</p>
              {index < 3 && (
                <motion.div
                  initial={{ scaleX: 0 }}
                  animate={{ scaleX: 1 }}
                  transition={{ delay: 0.4 + index * 0.1, duration: 0.6 }}
                  className="mt-3 h-0.5 origin-left rounded-full bg-gradient-to-r from-cyan-300/60 to-transparent"
                />
              )}
            </div>
          ))}
        </motion.div>

        <DemoFlow snapshot={snapshot} />
        <div className="grid gap-6 lg:grid-cols-[0.92fr_1.08fr]">
        <GlassCard title="比赛作品快速定制" eyebrow="你可以直接改成自己的参赛题目">
          <div className="grid gap-4">
            <label className="grid gap-2 text-sm text-slate-300">
              作品名称
              <input
                value={input.name}
                onChange={(event) => updateInput({ name: event.target.value })}
                className="rounded-2xl border border-white/10 bg-slate-950/40 px-4 py-3 text-white outline-none transition focus:border-cyan-300/40 focus:ring-2 focus:ring-cyan-300/15"
              />
            </label>
            <label className="grid gap-2 text-sm text-slate-300">
              目标用户
              <input
                value={input.audience}
                onChange={(event) => updateInput({ audience: event.target.value })}
                className="rounded-2xl border border-white/10 bg-slate-950/40 px-4 py-3 text-white outline-none transition focus:border-cyan-300/40 focus:ring-2 focus:ring-cyan-300/15"
              />
            </label>
            <label className="grid gap-2 text-sm text-slate-300">
              核心痛点
              <textarea
                value={input.painPoint}
                onChange={(event) => updateInput({ painPoint: event.target.value })}
                rows={4}
                className="rounded-2xl border border-white/10 bg-slate-950/40 px-4 py-3 text-white outline-none transition focus:border-cyan-300/40 focus:ring-2 focus:ring-cyan-300/15"
              />
            </label>
            <label className="grid gap-2 text-sm text-slate-300">
              赛道聚焦
              <input
                value={input.focus}
                onChange={(event) => updateInput({ focus: event.target.value })}
                className="rounded-2xl border border-white/10 bg-slate-950/40 px-4 py-3 text-white outline-none transition focus:border-cyan-300/40 focus:ring-2 focus:ring-cyan-300/15"
              />
            </label>
            <button
              type="button"
              onClick={handleRegenerate}
              className="inline-flex items-center justify-center gap-2 rounded-2xl bg-gradient-to-r from-cyan-300 to-emerald-300 px-4 py-3 text-sm font-semibold text-slate-950 transition hover:brightness-110"
            >
              <WandSparkles className="h-4 w-4" />
              重新生成作品蓝图
            </button>
          </div>
        </GlassCard>
        <div className="grid gap-6">
          <GlassCard title="为什么这个作品适合比赛" eyebrow="核心价值一目了然">
            <div className="grid gap-4 md:grid-cols-3">
              {featureCards.map(({ title, desc, Icon }, index) => {
                return (
                  <motion.div
                    key={title}
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ delay: 0.1 + index * 0.08 }}
                    className="rounded-3xl border border-white/10 bg-slate-950/30 p-4 transition hover:border-cyan-300/30 hover:bg-slate-950/50"
                  >
                    <Icon className="h-5 w-5 text-cyan-200" />
                    <p className="mt-3 text-base font-medium text-white">{title}</p>
                    <p className="mt-2 text-sm leading-6 text-slate-400">{desc}</p>
                  </motion.div>
                );
              })}
            </div>
          </GlassCard>
          <GlassCard title="当前自动生成结果" eyebrow="开场时可直接展示">
            <div className="space-y-3">
              <p className="text-sm uppercase tracking-[0.24em] text-slate-500">项目名称</p>
              <p className="text-2xl font-semibold text-white">{snapshot.profile.name}</p>
              <p className="text-sm leading-7 text-slate-300">{snapshot.deliverables.applicationSummary}</p>
              <div className="grid gap-3 pt-2 md:grid-cols-3">
                <div className="rounded-2xl border border-white/10 bg-slate-950/30 p-3">
                  <p className="text-[10px] uppercase tracking-[0.22em] text-slate-500">任务数</p>
                  <p className="mt-2 text-lg font-semibold text-white">
                    {snapshot.modules.reduce((sum, module) => sum + module.tasks.length, 0)}
                  </p>
                </div>
                <div className="rounded-2xl border border-white/10 bg-slate-950/30 p-3">
                  <p className="text-[10px] uppercase tracking-[0.22em] text-slate-500">证据数</p>
                  <p className="mt-2 text-lg font-semibold text-white">{snapshot.evidence.length}</p>
                </div>
                <div className="rounded-2xl border border-white/10 bg-slate-950/30 p-3">
                  <p className="text-[10px] uppercase tracking-[0.22em] text-slate-500">导出文档</p>
                  <p className="mt-2 text-lg font-semibold text-white">{snapshot.documents.length}</p>
                </div>
              </div>
            </div>
          </GlassCard>
        </div>
        </div>
      </div>
    </AppShell>
  );
}
