import { useState } from "react";
import { Check, Download, Package } from "lucide-react";
import { useToast } from "@/components/Toast";
import type { ExportDocument } from "@/utils/workspace";

interface BulkExportProps {
  documents: ExportDocument[];
  projectName: string;
}

/**
 * 一键打包导出全部成果材料
 * 把申报书、PPT文案、讲稿等合并为一个完整的 Markdown 成果包下载，
 * 补齐"开发完成"到"成果可交付"的最后一环。
 */
export function BulkExport({ documents, projectName }: BulkExportProps) {
  const { notify } = useToast();
  const [exported, setExported] = useState(false);

  const handleBulkExport = () => {
    const header = [
      `# ${projectName} · 完整成果包`,
      "",
      `> 本文件由 TRAE 学创工作台「一键打包」生成，包含全部 ${documents.length} 份成果材料。`,
      `> 生成时间：${new Date().toLocaleString("zh-CN", { hour12: false })}`,
      "",
      "---",
      "",
    ].join("\n");

    const body = documents
      .map((doc) => [`## ${doc.title}`, "", `*文件名：${doc.fileName}*`, "", doc.content, "", "---", ""].join("\n"))
      .join("\n");

    const content = header + body;
    const blob = new Blob([content], { type: "text/markdown;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `${projectName}-完整成果包.md`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    setExported(true);
    notify(`已打包导出 ${documents.length} 份材料`);
    window.setTimeout(() => setExported(false), 2200);
  };

  return (
    <button
      type="button"
      onClick={handleBulkExport}
      className="inline-flex items-center gap-2 rounded-full bg-gradient-to-r from-cyan-300 to-emerald-300 px-5 py-2.5 text-sm font-semibold text-slate-950 shadow-[0_0_32px_rgba(79,209,255,0.3)] transition hover:brightness-110 hover:shadow-[0_0_40px_rgba(79,209,255,0.45)]"
    >
      {exported ? <Check className="h-4 w-4" /> : <Package className="h-4 w-4" />}
      {exported ? "已导出完整成果包" : "一键打包全部材料"}
      <Download className="h-3.5 w-3.5 opacity-70" />
    </button>
  );
}
