import { CheckCircle2, FileOutput, Gauge, Mic2, Workflow } from "lucide-react";
import { AppShell } from "@/components/AppShell";
import { GlassCard } from "@/components/GlassCard";
import { useWorkspaceStore } from "@/hooks/useWorkspaceStore";

export default function DefenseMode() {
  const { snapshot } = useWorkspaceStore();
  const totalTasks = snapshot.modules.reduce((sum, module) => sum + module.tasks.length, 0);
  const completedTasks = snapshot.modules.reduce(
    (sum, module) => sum + module.tasks.filter((task) => task.status === "已完成").length,
    0,
  );

  return (
    <AppShell eyebrow="简洁展示模式" title="展示模式：只保留最该被看见的价值、证据与结果">
      <div className="space-y-6">
        <div className="grid gap-6 xl:grid-cols-[1.05fr_0.95fr]">
          <GlassCard title="30 秒项目开场" eyebrow="先讲清问题，再讲清价值">
            <div className="rounded-[28px] border border-cyan-300/20 bg-cyan-300/10 p-5">
              <p className="text-lg leading-9 text-white">{snapshot.deliverables.openingPitch}</p>
            </div>
            <div className="mt-4 grid gap-3 md:grid-cols-3">
              <div className="rounded-2xl border border-white/10 bg-slate-950/30 p-4">
                <p className="text-[10px] uppercase tracking-[0.22em] text-slate-500">任务完成</p>
                <p className="mt-2 text-2xl font-semibold text-white">
                  {completedTasks} / {totalTasks}
                </p>
              </div>
              <div className="rounded-2xl border border-white/10 bg-slate-950/30 p-4">
                <p className="text-[10px] uppercase tracking-[0.22em] text-slate-500">过程证据</p>
                <p className="mt-2 text-2xl font-semibold text-white">{snapshot.evidence.length}</p>
              </div>
              <div className="rounded-2xl border border-white/10 bg-slate-950/30 p-4">
                <p className="text-[10px] uppercase tracking-[0.22em] text-slate-500">导出材料</p>
                <p className="mt-2 text-2xl font-semibold text-white">{snapshot.documents.length}</p>
              </div>
            </div>
          </GlassCard>

          <GlassCard title="核心证明" eyebrow="最值得被看见的三件事">
            <div className="space-y-3">
              {[
                {
                  title: "有真实操作",
                  detail: "任务、证据、提示词、版本日志都能现场新增和修改，完成度会实时变化。",
                  Icon: Workflow,
                },
                {
                  title: "有真实产出",
                  detail: "系统会基于当前状态自动生成正式申报书、PPT 文案与 3 分钟讲稿。",
                  Icon: FileOutput,
                },
                {
                  title: "有完整闭环",
                  detail: "它把 TRAE 真正拉进“构思-开发-整理-展示”的全流程闭环。",
                  Icon: Gauge,
                },
              ].map(({ title, detail, Icon }) => (
                <div key={title} className="rounded-2xl border border-white/10 bg-slate-950/30 p-4">
                  <div className="flex items-start gap-3">
                    <div className="rounded-2xl border border-emerald-300/20 bg-emerald-300/10 p-2">
                      <Icon className="h-4 w-4 text-emerald-100" />
                    </div>
                    <div>
                      <p className="text-sm font-semibold text-white">{title}</p>
                      <p className="mt-2 text-sm leading-6 text-slate-300">{detail}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </GlassCard>
        </div>

        <div className="grid gap-6 xl:grid-cols-[0.95fr_1.05fr]">
          <GlassCard title="3 分钟讲稿摘要" eyebrow="展示口播主线">
            <div className="space-y-3">
              {snapshot.deliverables.speechMarkdown
                .split("\n")
                .filter((line) => line.trim() && !line.startsWith("#"))
                .slice(0, 5)
                .map((line) => (
                  <div key={line} className="flex items-start gap-3 rounded-2xl border border-white/10 bg-slate-950/30 p-4">
                    <Mic2 className="mt-1 h-4 w-4 text-cyan-200" />
                    <p className="text-sm leading-6 text-slate-300">{line}</p>
                  </div>
                ))}
            </div>
          </GlassCard>

          <GlassCard title="推荐展示顺序" eyebrow="建议按这个节奏讲">
            <div className="space-y-3">
              {snapshot.deliverables.pptOutline.map((item, index) => (
                <div key={item} className="flex items-start gap-3 rounded-2xl border border-white/10 bg-slate-950/30 p-4">
                  <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-white/10 text-sm font-semibold text-white">
                    {index + 1}
                  </div>
                  <p className="text-sm leading-6 text-slate-300">{item}</p>
                </div>
              ))}
            </div>
          </GlassCard>
        </div>

        <div className="grid gap-4 xl:grid-cols-3">
          {snapshot.documents.slice(0, 3).map((document) => (
            <GlassCard key={document.id} title={document.title} eyebrow={document.fileName}>
              <p className="text-sm leading-6 text-slate-300">{document.description}</p>
              <div className="mt-4 rounded-2xl border border-white/10 bg-slate-950/35 p-3">
                <p className="text-xs leading-6 text-slate-400">
                  {document.content.split("\n").filter(Boolean).slice(0, 4).join(" / ")}
                </p>
              </div>
            </GlassCard>
          ))}
        </div>

        <GlassCard title="结尾总结句" eyebrow="适合最后 15 秒使用">
          <div className="flex items-start gap-3 rounded-3xl border border-emerald-300/15 bg-emerald-300/10 p-5">
            <CheckCircle2 className="mt-1 h-5 w-5 text-emerald-100" />
            <p className="text-base leading-8 text-emerald-50">
              我希望 TRAE 不只帮人写出一段代码，而是帮助一个普通学生独立完成一份真正像样的作品。
            </p>
          </div>
        </GlassCard>
      </div>
    </AppShell>
  );
}
