import { useMemo, useState } from "react";
import { Check, Copy, Download, FileOutput } from "lucide-react";
import { GlassCard } from "@/components/GlassCard";
import { useToast } from "@/components/Toast";
import { copyDocumentContent, downloadDocument } from "@/utils/exporter";
import type { ExportDocument } from "@/utils/workspace";

interface ExportCenterProps {
  documents: ExportDocument[];
}

export function ExportCenter({ documents }: ExportCenterProps) {
  const { notify } = useToast();
  const [activeId, setActiveId] = useState<ExportDocument["id"]>(documents[0]?.id ?? "application");
  const [copiedId, setCopiedId] = useState<string | null>(null);

  const activeDocument = useMemo(
    () => documents.find((item) => item.id === activeId) ?? documents[0],
    [activeId, documents],
  );

  if (!activeDocument) return null;

  return (
    <GlassCard title="材料导出中心" eyebrow="复制 + 下载双模式，直接交付而不是停留在展示">
      <div className="grid gap-5 xl:grid-cols-[0.36fr_0.64fr]">
        <div className="space-y-3">
          {documents.map((document) => (
            <button
              key={document.id}
              type="button"
              onClick={() => setActiveId(document.id)}
              className={`w-full rounded-2xl border p-4 text-left transition ${
                document.id === activeId
                  ? "border-cyan-300/35 bg-cyan-300/10 shadow-[0_0_24px_rgba(79,209,255,0.12)]"
                  : "border-white/10 bg-slate-950/30 hover:border-cyan-300/20"
              }`}
            >
              <div className="flex items-center gap-3">
                <div className="rounded-xl border border-white/10 bg-white/5 p-2">
                  <FileOutput className="h-4 w-4 text-cyan-100" />
                </div>
                <div>
                  <p className="text-sm font-semibold text-white">{document.title}</p>
                  <p className="mt-1 text-xs leading-5 text-slate-400">{document.description}</p>
                </div>
              </div>
            </button>
          ))}
        </div>
        <div className="rounded-[28px] border border-white/10 bg-slate-950/30 p-4">
          <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
            <div>
              <p className="text-sm font-semibold text-white">{activeDocument.title}</p>
              <p className="mt-1 text-xs text-slate-400">{activeDocument.fileName}</p>
            </div>
            <div className="flex flex-wrap gap-2">
              <button
                type="button"
                onClick={async () => {
                  await copyDocumentContent(activeDocument.content);
                  setCopiedId(activeDocument.id);
                  notify("已复制到剪贴板");
                  window.setTimeout(() => setCopiedId(null), 1200);
                }}
                className="inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/10 px-4 py-2 text-sm text-white transition hover:border-cyan-300/30"
              >
                {copiedId === activeDocument.id ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
                {copiedId === activeDocument.id ? "已复制" : "复制内容"}
              </button>
              <button
                type="button"
                onClick={() => {
                  downloadDocument(activeDocument);
                  notify(`已下载 ${activeDocument.fileName}`);
                }}
                className="inline-flex items-center gap-2 rounded-full bg-white px-4 py-2 text-sm font-medium text-slate-950 transition hover:bg-cyan-200"
              >
                <Download className="h-4 w-4" />
                下载文件
              </button>
            </div>
          </div>
          <pre className="max-h-[520px] overflow-auto rounded-2xl border border-white/10 bg-[#050814] p-4 text-xs leading-6 text-slate-200 whitespace-pre-wrap">
            {activeDocument.content}
          </pre>
        </div>
      </div>
    </GlassCard>
  );
}
