import { ClipboardList, FileText, Presentation } from "lucide-react";
import type { DeliverablePack } from "@/utils/workspace";
import { GlassCard } from "@/components/GlassCard";

export function DeliverablePanel({ deliverables }: { deliverables: DeliverablePack }) {
  return (
    <div className="grid gap-4 xl:grid-cols-[1.1fr_0.9fr]">
      <GlassCard title="30 秒项目开场" eyebrow="展示即用">
        <div className="rounded-3xl border border-emerald-300/20 bg-emerald-300/10 p-5">
          <p className="text-base leading-8 text-emerald-50">{deliverables.openingPitch}</p>
        </div>
        <div className="mt-4 inline-flex items-center gap-2 text-xs uppercase tracking-[0.22em] text-slate-400">
          <Presentation className="h-3.5 w-3.5" />
          用于开场页与展示口播
        </div>
      </GlassCard>
      <div className="grid gap-4">
        <GlassCard title="申报书简介" eyebrow="可直接填表">
          <div className="flex items-start gap-3">
            <FileText className="mt-1 h-4 w-4 text-cyan-200" />
            <p className="text-sm leading-7 text-slate-300">{deliverables.applicationSummary}</p>
          </div>
        </GlassCard>
        <GlassCard title="演示脚本" eyebrow="4 步串讲">
          <div className="space-y-3">
            {deliverables.demoScript.map((step) => (
              <div key={step} className="flex items-start gap-3 rounded-2xl border border-white/8 bg-slate-950/30 p-3">
                <ClipboardList className="mt-1 h-4 w-4 text-amber-200" />
                <p className="text-sm leading-6 text-slate-300">{step}</p>
              </div>
            ))}
          </div>
        </GlassCard>
      </div>
    </div>
  );
}
