import { useMemo, useState } from "react";
import { CheckCheck, ListTodo, Plus } from "lucide-react";
import { GlassCard } from "@/components/GlassCard";
import { useToast } from "@/components/Toast";
import { useWorkspaceStore } from "@/hooks/useWorkspaceStore";
import type { ModuleId, TaskStage, TaskStatus } from "@/utils/workspace";

const stages: TaskStage[] = ["构思", "设计", "开发", "调试", "展示"];
const statuses: TaskStatus[] = ["待开始", "进行中", "已完成"];

export function TaskBoard() {
  const { snapshot, addTask, setTaskStatus } = useWorkspaceStore();
  const { notify } = useToast();
  const [drafts, setDrafts] = useState<Record<ModuleId, { title: string; stage: TaskStage; note: string }>>({
    ideation: { title: "", stage: "构思", note: "" },
    development: { title: "", stage: "开发", note: "" },
    documentation: { title: "", stage: "展示", note: "" },
    growth: { title: "", stage: "展示", note: "" },
  });

  const overall = useMemo(() => {
    const tasks = snapshot.modules.flatMap((module) => module.tasks);
    const completed = tasks.filter((task) => task.status === "已完成").length;
    return { total: tasks.length, completed };
  }, [snapshot.modules]);

  return (
    <GlassCard title="真实任务推进区" eyebrow="新增任务、切换状态、实时影响完成度">
      <div className="mb-5 flex items-center justify-between rounded-3xl border border-white/10 bg-slate-950/35 p-4">
        <div>
          <p className="text-xs uppercase tracking-[0.24em] text-slate-500">当前进度</p>
          <p className="mt-2 text-base font-semibold text-white">
            已完成 {overall.completed} / {overall.total} 项任务
          </p>
        </div>
        <div className="inline-flex items-center gap-2 rounded-full border border-emerald-300/20 bg-emerald-300/10 px-3 py-2 text-xs text-emerald-100">
          <CheckCheck className="h-3.5 w-3.5" />
          状态变化会同步到成果摘要
        </div>
      </div>
      <div className="grid gap-5 xl:grid-cols-2">
        {snapshot.modules.map((module) => (
          <div key={module.id} className="rounded-[28px] border border-white/10 bg-slate-950/28 p-4">
            <div className="mb-4 flex items-center justify-between gap-3">
              <div>
                <p className="text-sm font-semibold text-white">{module.title}</p>
                <p className="mt-1 text-xs leading-5 text-slate-400">{module.summary}</p>
              </div>
              <div className="rounded-full border border-cyan-300/20 bg-cyan-300/10 px-3 py-1 text-xs text-cyan-100">
                {module.completion}%
              </div>
            </div>
            <div className="space-y-3">
              {module.tasks.map((task) => (
                <div key={task.id} className="rounded-2xl border border-white/8 bg-black/20 p-3">
                  <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
                    <div className="space-y-1">
                      <div className="flex flex-wrap items-center gap-2">
                        <ListTodo className="h-4 w-4 text-cyan-200" />
                        <p className="text-sm font-medium text-white">{task.title}</p>
                        <span className="rounded-full border border-white/10 px-2 py-0.5 text-[10px] tracking-[0.2em] text-slate-400">
                          {task.stage}
                        </span>
                      </div>
                      <p className="text-xs leading-5 text-slate-400">{task.note}</p>
                    </div>
                    <select
                      aria-label={`${task.title} 状态`}
                      value={task.status}
                      onChange={(event) => setTaskStatus(module.id, task.id, event.target.value as TaskStatus)}
                      className="rounded-xl border border-white/10 bg-slate-900 px-3 py-2 text-sm text-white outline-none"
                    >
                      {statuses.map((status) => (
                        <option key={status} value={status}>
                          {status}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>
              ))}
            </div>
            <div className="mt-4 grid gap-3 rounded-2xl border border-dashed border-white/10 bg-white/5 p-3">
              <input
                value={drafts[module.id].title}
                onChange={(event) =>
                  setDrafts((current) => ({
                    ...current,
                    [module.id]: { ...current[module.id], title: event.target.value },
                  }))
                }
                placeholder="新增一个真实任务，例如：补充正式展示讲稿"
                className="rounded-xl border border-white/10 bg-slate-900 px-3 py-2 text-sm text-white outline-none"
              />
              <div className="grid gap-3 md:grid-cols-[120px_1fr]">
                <select
                  value={drafts[module.id].stage}
                  onChange={(event) =>
                    setDrafts((current) => ({
                      ...current,
                      [module.id]: { ...current[module.id], stage: event.target.value as TaskStage },
                    }))
                  }
                  className="rounded-xl border border-white/10 bg-slate-900 px-3 py-2 text-sm text-white outline-none"
                >
                  {stages.map((stage) => (
                    <option key={stage} value={stage}>
                      {stage}
                    </option>
                  ))}
                </select>
                <input
                  value={drafts[module.id].note}
                  onChange={(event) =>
                    setDrafts((current) => ({
                      ...current,
                      [module.id]: { ...current[module.id], note: event.target.value },
                    }))
                  }
                  placeholder="备注：这个任务准备解决什么问题"
                  className="rounded-xl border border-white/10 bg-slate-900 px-3 py-2 text-sm text-white outline-none"
                />
              </div>
              <button
                type="button"
                onClick={() => {
                  const draft = drafts[module.id];
                  if (!draft.title.trim()) return;
                  addTask({
                    moduleId: module.id,
                    title: draft.title.trim(),
                    stage: draft.stage,
                    note: draft.note.trim() || "由用户在工作台新增。",
                  });
                  setDrafts((current) => ({
                    ...current,
                    [module.id]: { ...current[module.id], title: "", note: "" },
                  }));
                  notify(`已新增任务到「${module.title}」`);
                }}
                className="inline-flex items-center justify-center gap-2 rounded-xl bg-white px-4 py-2 text-sm font-medium text-slate-950 transition hover:bg-cyan-200"
              >
                <Plus className="h-4 w-4" />
                新增任务
              </button>
            </div>
          </div>
        ))}
      </div>
    </GlassCard>
  );
}
