import { useState } from "react";
import { Bot, GitCommitHorizontal, PlusCircle, Sparkles } from "lucide-react";
import { GlassCard } from "@/components/GlassCard";
import { useWorkspaceStore } from "@/hooks/useWorkspaceStore";

export function PromptVersionStudio() {
  const { snapshot, addPrompt, addVersion } = useWorkspaceStore();
  const [promptDraft, setPromptDraft] = useState({
    scene: "",
    prompt: "",
    outcome: "",
  });
  const [versionDraft, setVersionDraft] = useState({
    version: "",
    summary: "",
    impact: "",
  });

  return (
    <GlassCard title="提示词与版本工作区" eyebrow="让 TRAE 的使用过程看得见、讲得出、留得住">
      <div className="grid gap-6 xl:grid-cols-2">
        <div className="space-y-4 rounded-[28px] border border-white/10 bg-slate-950/28 p-4">
          <div className="flex items-center gap-3">
            <div className="rounded-2xl border border-cyan-300/20 bg-cyan-300/10 p-2">
              <Bot className="h-4 w-4 text-cyan-100" />
            </div>
            <div>
              <p className="text-sm font-semibold text-white">提示词记录</p>
              <p className="text-xs text-slate-400">记录某次关键提问及 TRAE 给你的有效结果。</p>
            </div>
          </div>
          <div className="grid gap-3">
            <input
              value={promptDraft.scene}
              onChange={(event) => setPromptDraft((current) => ({ ...current, scene: event.target.value }))}
              placeholder="场景，例如：优化展示逻辑"
              className="rounded-xl border border-white/10 bg-slate-900 px-3 py-2 text-sm text-white outline-none"
            />
            <textarea
              rows={4}
              value={promptDraft.prompt}
              onChange={(event) => setPromptDraft((current) => ({ ...current, prompt: event.target.value }))}
              placeholder="输入你真实使用的提示词"
              className="rounded-xl border border-white/10 bg-slate-900 px-3 py-2 text-sm text-white outline-none"
            />
            <textarea
              rows={3}
              value={promptDraft.outcome}
              onChange={(event) => setPromptDraft((current) => ({ ...current, outcome: event.target.value }))}
              placeholder="这次提示词带来了什么结果"
              className="rounded-xl border border-white/10 bg-slate-900 px-3 py-2 text-sm text-white outline-none"
            />
            <button
              type="button"
              onClick={() => {
                if (!promptDraft.scene.trim() || !promptDraft.prompt.trim() || !promptDraft.outcome.trim()) return;
                addPrompt({
                  scene: promptDraft.scene.trim(),
                  prompt: promptDraft.prompt.trim(),
                  outcome: promptDraft.outcome.trim(),
                });
                setPromptDraft({ scene: "", prompt: "", outcome: "" });
              }}
              className="inline-flex items-center justify-center gap-2 rounded-xl bg-white px-4 py-2 text-sm font-medium text-slate-950 transition hover:bg-cyan-200"
            >
              <PlusCircle className="h-4 w-4" />
              新增提示词记录
            </button>
          </div>
          <div className="space-y-3">
            {snapshot.prompts.map((item) => (
              <div key={item.id} className="rounded-2xl border border-white/10 bg-black/20 p-3">
                <div className="flex items-center justify-between gap-3">
                  <p className="text-sm font-semibold text-white">{item.scene}</p>
                  <span className="text-[11px] text-slate-500">{item.createdAt}</span>
                </div>
                <p className="mt-2 text-xs leading-5 text-cyan-100/90">{item.prompt}</p>
                <p className="mt-2 text-xs leading-5 text-slate-300">结果：{item.outcome}</p>
              </div>
            ))}
          </div>
        </div>

        <div className="space-y-4 rounded-[28px] border border-white/10 bg-slate-950/28 p-4">
          <div className="flex items-center gap-3">
            <div className="rounded-2xl border border-emerald-300/20 bg-emerald-300/10 p-2">
              <GitCommitHorizontal className="h-4 w-4 text-emerald-100" />
            </div>
            <div>
              <p className="text-sm font-semibold text-white">版本迭代日志</p>
              <p className="text-xs text-slate-400">记录每次升级做了什么，以及为什么更强。</p>
            </div>
          </div>
          <div className="grid gap-3">
            <input
              value={versionDraft.version}
              onChange={(event) => setVersionDraft((current) => ({ ...current, version: event.target.value }))}
              placeholder="版本号，例如：v0.3 强化版"
              className="rounded-xl border border-white/10 bg-slate-900 px-3 py-2 text-sm text-white outline-none"
            />
            <textarea
              rows={3}
              value={versionDraft.summary}
              onChange={(event) => setVersionDraft((current) => ({ ...current, summary: event.target.value }))}
              placeholder="本次迭代做了什么"
              className="rounded-xl border border-white/10 bg-slate-900 px-3 py-2 text-sm text-white outline-none"
            />
            <textarea
              rows={3}
              value={versionDraft.impact}
              onChange={(event) => setVersionDraft((current) => ({ ...current, impact: event.target.value }))}
              placeholder="这次迭代解决了什么问题、带来了什么效果"
              className="rounded-xl border border-white/10 bg-slate-900 px-3 py-2 text-sm text-white outline-none"
            />
            <button
              type="button"
              onClick={() => {
                if (!versionDraft.version.trim() || !versionDraft.summary.trim() || !versionDraft.impact.trim()) return;
                addVersion({
                  version: versionDraft.version.trim(),
                  summary: versionDraft.summary.trim(),
                  impact: versionDraft.impact.trim(),
                });
                setVersionDraft({ version: "", summary: "", impact: "" });
              }}
              className="inline-flex items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-cyan-300 to-emerald-300 px-4 py-2 text-sm font-semibold text-slate-950 transition hover:brightness-110"
            >
              <Sparkles className="h-4 w-4" />
              记录版本升级
            </button>
          </div>
          <div className="space-y-3">
            {snapshot.versions.map((item) => (
              <div key={item.id} className="rounded-2xl border border-white/10 bg-black/20 p-3">
                <div className="flex items-center justify-between gap-3">
                  <p className="text-sm font-semibold text-white">{item.version}</p>
                  <span className="text-[11px] text-slate-500">{item.createdAt}</span>
                </div>
                <p className="mt-2 text-xs leading-5 text-slate-300">更新：{item.summary}</p>
                <p className="mt-2 text-xs leading-5 text-emerald-100/90">影响：{item.impact}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </GlassCard>
  );
}
