import { useState } from "react";
import { Braces, Bug, FilePenLine, PlusSquare } from "lucide-react";
import { GlassCard } from "@/components/GlassCard";
import { useWorkspaceStore } from "@/hooks/useWorkspaceStore";
import type { EvidenceItem } from "@/utils/workspace";

const tagOptions: EvidenceItem["tag"][] = ["构思", "设计", "开发", "调试", "展示", "文档", "版本"];

const tagIcon = {
  构思: FilePenLine,
  设计: FilePenLine,
  开发: Braces,
  调试: Bug,
  展示: FilePenLine,
  文档: FilePenLine,
  版本: PlusSquare,
};

export function EvidenceManager() {
  const { snapshot, addEvidence } = useWorkspaceStore();
  const [title, setTitle] = useState("");
  const [detail, setDetail] = useState("");
  const [tag, setTag] = useState<EvidenceItem["tag"]>("开发");

  return (
    <GlassCard title="TRAE 使用证据系统" eyebrow="不再只是说用了 TRAE，而是把过程记录下来">
      <div className="grid gap-5 xl:grid-cols-[0.9fr_1.1fr]">
        <div className="rounded-[28px] border border-white/10 bg-slate-950/30 p-4">
          <p className="text-sm font-semibold text-white">新增一条真实证据</p>
          <p className="mt-2 text-xs leading-5 text-slate-400">
            可以记录提示词、页面调整、报错修复、版本备注、文档生成等内容。在展示或申报时，这部分能直接体现你的真实开发过程。
          </p>
          <div className="mt-4 grid gap-3">
            <input
              value={title}
              onChange={(event) => setTitle(event.target.value)}
              placeholder="标题，例如：修复导出文档格式"
              className="rounded-xl border border-white/10 bg-slate-900 px-3 py-2 text-sm text-white outline-none"
            />
            <select
              value={tag}
              onChange={(event) => setTag(event.target.value as EvidenceItem["tag"])}
              className="rounded-xl border border-white/10 bg-slate-900 px-3 py-2 text-sm text-white outline-none"
            >
              {tagOptions.map((option) => (
                <option key={option} value={option}>
                  {option}
                </option>
              ))}
            </select>
            <textarea
              rows={6}
              value={detail}
              onChange={(event) => setDetail(event.target.value)}
              placeholder="描述你在 TRAE 中做了什么、解决了什么问题、产出了什么结果"
              className="rounded-xl border border-white/10 bg-slate-900 px-3 py-2 text-sm text-white outline-none"
            />
            <button
              type="button"
              onClick={() => {
                if (!title.trim() || !detail.trim()) return;
                addEvidence({ title: title.trim(), detail: detail.trim(), tag });
                setTitle("");
                setDetail("");
                setTag("开发");
              }}
              className="inline-flex items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-cyan-300 to-emerald-300 px-4 py-2 text-sm font-semibold text-slate-950 transition hover:brightness-110"
            >
              <PlusSquare className="h-4 w-4" />
              记录证据
            </button>
          </div>
        </div>
        <div className="space-y-3">
          {snapshot.evidence.map((item) => {
            const Icon = tagIcon[item.tag];
            return (
              <div key={item.id} className="rounded-[24px] border border-white/10 bg-slate-950/28 p-4">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex items-start gap-3">
                    <div className="rounded-2xl border border-cyan-300/20 bg-cyan-300/10 p-2">
                      <Icon className="h-4 w-4 text-cyan-100" />
                    </div>
                    <div>
                      <div className="flex flex-wrap items-center gap-2">
                        <p className="text-sm font-semibold text-white">{item.title}</p>
                        <span className="rounded-full border border-white/10 px-2 py-0.5 text-[10px] tracking-[0.2em] text-slate-400">
                          {item.tag}
                        </span>
                      </div>
                      <p className="mt-2 text-sm leading-6 text-slate-300">{item.detail}</p>
                    </div>
                  </div>
                  <span className="text-[11px] text-slate-500">{item.createdAt}</span>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </GlassCard>
  );
}
