import { motion } from "framer-motion";
import { CheckCircle2, CircleDashed, CircleEllipsis } from "lucide-react";
import type { ModulePlan } from "@/utils/workspace";
import { GlassCard } from "@/components/GlassCard";

const statusIcon = {
  已完成: CheckCircle2,
  进行中: CircleEllipsis,
  待开始: CircleDashed,
};

export function ModuleProgressCard({ module }: { module: ModulePlan }) {
  return (
    <GlassCard title={module.title} eyebrow={`${module.completion}% 进度`}>
      <div className="space-y-4">
        <p className="text-sm leading-6 text-slate-300">{module.summary}</p>
        <div className="h-2 rounded-full bg-white/10">
          <motion.div
            initial={{ width: 0 }}
            animate={{ width: `${module.completion}%` }}
            transition={{ duration: 0.8, ease: "easeOut" }}
            className="h-2 rounded-full bg-gradient-to-r from-cyan-300 via-sky-400 to-emerald-300"
          />
        </div>
        <div className="space-y-3">
          {module.tasks.map((task) => {
            const Icon = statusIcon[task.status];
            return (
              <div key={task.id} className="rounded-2xl border border-white/8 bg-slate-950/35 p-3">
                <div className="flex items-start gap-3">
                  <Icon className="mt-0.5 h-4 w-4 text-cyan-200" />
                  <div>
                    <div className="flex flex-wrap items-center gap-2">
                      <p className="text-sm font-medium text-white">{task.title}</p>
                      <span className="rounded-full border border-white/10 bg-white/5 px-2 py-0.5 text-[10px] tracking-[0.2em] text-slate-300">
                        {task.stage}
                      </span>
                    </div>
                    <p className="mt-1 text-xs leading-5 text-slate-400">{task.note}</p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </GlassCard>
  );
}
