import { create } from "zustand";
import { persist } from "zustand/middleware";
import type { NewEvidenceInput, NewPromptInput, NewTaskInput, NewVersionInput, ProjectInput, TaskStatus, WorkspaceSnapshot } from "@/utils/workspace";
import { appendEvidenceItem, appendPromptRecord, appendTask, appendVersionRecord, buildWorkspaceSnapshot, refreshWorkspaceSnapshot, updateTaskStatus } from "@/utils/workspace";

interface WorkspaceState {
  input: ProjectInput;
  snapshot: WorkspaceSnapshot;
  highlightedQuestion: string;
  updateInput: (patch: Partial<ProjectInput>) => void;
  regenerate: () => void;
  addTask: (input: NewTaskInput) => void;
  setTaskStatus: (moduleId: NewTaskInput["moduleId"], taskId: string, status: TaskStatus) => void;
  addEvidence: (input: NewEvidenceInput) => void;
  addPrompt: (input: NewPromptInput) => void;
  addVersion: (input: NewVersionInput) => void;
  randomizeQuestion: () => void;
}

const defaultInput: ProjectInput = {
  name: "TRAE 学创工作台",
  audience: "学生与单人独立开发者",
  painPoint: "使用 TRAE 时只能零散生成内容，难以完成完整项目闭环。",
  focus: "学习工作赛道与青少年普惠教育",
};

const mockQuestions = [
  "如果有人质疑你的作品只是文档包装，你如何证明 TRAE 真正参与了开发全过程？",
  "为什么你的作品更适合单人参赛者，而不是团队型项目？",
  "你的方案如何兼顾工具效率与教育普惠价值？",
];

function normalizeStageLabel(stage: string) {
  return stage === "答辩" ? "展示" : stage;
}

export const useWorkspaceStore = create<WorkspaceState>()(
  persist(
    (set, get) => ({
      input: defaultInput,
      snapshot: buildWorkspaceSnapshot(defaultInput),
      highlightedQuestion: mockQuestions[0],
      updateInput: (patch) =>
        set((state) => {
          const nextInput = { ...state.input, ...patch };
          return {
            input: nextInput,
            snapshot: refreshWorkspaceSnapshot(
              nextInput,
              state.snapshot.modules,
              state.snapshot.evidence,
              state.snapshot.prompts,
              state.snapshot.versions,
            ),
          };
        }),
      regenerate: () =>
        set((state) => ({
          snapshot: refreshWorkspaceSnapshot(
            state.input,
            state.snapshot.modules,
            state.snapshot.evidence,
            state.snapshot.prompts,
            state.snapshot.versions,
          ),
        })),
      addTask: (taskInput) =>
        set((state) => {
          const nextModules = appendTask(state.snapshot.modules, taskInput);
          return {
            snapshot: refreshWorkspaceSnapshot(
              state.input,
              nextModules,
              state.snapshot.evidence,
              state.snapshot.prompts,
              state.snapshot.versions,
            ),
          };
        }),
      setTaskStatus: (moduleId, taskId, status) =>
        set((state) => {
          const nextModules = updateTaskStatus(state.snapshot.modules, moduleId, taskId, status);
          return {
            snapshot: refreshWorkspaceSnapshot(
              state.input,
              nextModules,
              state.snapshot.evidence,
              state.snapshot.prompts,
              state.snapshot.versions,
            ),
          };
        }),
      addEvidence: (evidenceInput) =>
        set((state) => {
          const nextEvidence = appendEvidenceItem(state.snapshot.evidence, evidenceInput);
          return {
            snapshot: refreshWorkspaceSnapshot(
              state.input,
              state.snapshot.modules,
              nextEvidence,
              state.snapshot.prompts,
              state.snapshot.versions,
            ),
          };
        }),
      addPrompt: (promptInput) =>
        set((state) => {
          const nextPrompts = appendPromptRecord(state.snapshot.prompts, promptInput);
          return {
            snapshot: refreshWorkspaceSnapshot(
              state.input,
              state.snapshot.modules,
              state.snapshot.evidence,
              nextPrompts,
              state.snapshot.versions,
            ),
          };
        }),
      addVersion: (versionInput) =>
        set((state) => {
          const nextVersions = appendVersionRecord(state.snapshot.versions, versionInput);
          return {
            snapshot: refreshWorkspaceSnapshot(
              state.input,
              state.snapshot.modules,
              state.snapshot.evidence,
              state.snapshot.prompts,
              nextVersions,
            ),
          };
        }),
      randomizeQuestion: () => {
        const current = get().highlightedQuestion;
        const next = mockQuestions.find((item) => item !== current) ?? mockQuestions[0];
        set({ highlightedQuestion: next });
      },
    }),
    {
      name: "trae-studio-workspace",
      version: 2,
      migrate: (persistedState: unknown) => {
        const state = persistedState as Partial<WorkspaceState> | undefined;
        const input = state?.input ?? defaultInput;
        const snapshot = state?.snapshot;

        if (!snapshot) {
          return {
            ...state,
            input,
            snapshot: buildWorkspaceSnapshot(input),
            highlightedQuestion: state?.highlightedQuestion ?? mockQuestions[0],
          };
        }

        const migratedModules = snapshot.modules.map((module) => ({
          ...module,
          tasks: module.tasks.map((task) => ({
            ...task,
            stage: normalizeStageLabel(task.stage) as typeof task.stage,
          })),
        }));

        const migratedEvidence = snapshot.evidence.map((item) => ({
          ...item,
          tag: normalizeStageLabel(item.tag) as typeof item.tag,
        }));

        return {
          ...state,
          input,
          snapshot: refreshWorkspaceSnapshot(
            input,
            migratedModules,
            migratedEvidence,
            snapshot.prompts,
            snapshot.versions,
          ),
          highlightedQuestion: state?.highlightedQuestion ?? mockQuestions[0],
        };
      },
      partialize: (state) => ({
        input: state.input,
        snapshot: state.snapshot,
        highlightedQuestion: state.highlightedQuestion,
      }),
    },
  ),
);
