import type { ReactNode } from "react";
import { cn } from "@/lib/utils";

interface GlassCardProps {
  title?: string;
  eyebrow?: string;
  className?: string;
  children: ReactNode;
}

export function GlassCard({ title, eyebrow, className, children }: GlassCardProps) {
  return (
    <section className={cn("rounded-[28px] border border-white/10 bg-white/6 p-5 shadow-[0_16px_60px_rgba(8,12,29,0.38)] backdrop-blur-md", className)}>
      {(title || eyebrow) && (
        <div className="mb-4">
          {eyebrow ? <p className="text-xs uppercase tracking-[0.24em] text-cyan-200/80">{eyebrow}</p> : null}
          {title ? <h2 className="mt-2 text-lg font-semibold text-white">{title}</h2> : null}
        </div>
      )}
      {children}
    </section>
  );
}
