function buildProgressSummary(modules: ModulePlan[]) {
  const allTasks = modules.flatMap((module) => module.tasks);
  const completed = allTasks.filter((task) => task.status === "已完成").length;
  return {
    total: allTasks.length,
    completed,
    percent: allTasks.length ? Math.round((completed / allTasks.length) * 100) : 0,
  };
}

