function rebuildSnapshot(
  profile: ProjectProfile,
  modules: ModulePlan[],
  evidence: EvidenceItem[],
  prompts: PromptRecord[],
  versions: VersionRecord[],
): WorkspaceSnapshot {
  const deliverables = buildDeliverables(profile, modules, evidence, prompts, versions);
  return {
    profile,
    modules,
    deliverables,
    evidence,
    prompts,
    versions,
    documents: buildExportDocuments(profile, deliverables),
  };
}

export function updateTaskStatus(modules: ModulePlan[], moduleId: ModuleId, taskId: string, status: TaskStatus): ModulePlan[] {
  return modules.map((module) => {
    if (module.id !== moduleId) return module;
    const nextTasks = module.tasks.map((task) => (task.id === taskId ? { ...task, status } : task));
    return withCompletion({ ...module, tasks: nextTasks });
  });
}

export function appendTask(modules: ModulePlan[], input: NewTaskInput): ModulePlan[] {
  return modules.map((module) => {
    if (module.id !== input.moduleId) return module;
    const nextTasks = module.tasks.concat({
      id: createId("task"),
      title: input.title,
      stage: input.stage,
      status: "待开始",
      note: input.note,
    });
    return withCompletion({ ...module, tasks: nextTasks });
  });
}

export function appendEvidenceItem(items: EvidenceItem[], input: NewEvidenceInput): EvidenceItem[] {
  return [
    {
      id: createId("evidence"),
      title: input.title,
      detail: input.detail,
      tag: input.tag,
      createdAt: getNowLabel(),
    },
    ...items,
  ];
}

export function appendPromptRecord(items: PromptRecord[], input: NewPromptInput): PromptRecord[] {
  return [
    {
      id: createId("prompt"),
      scene: input.scene,
      prompt: input.prompt,
      outcome: input.outcome,
      createdAt: getNowLabel(),
    },
    ...items,
  ];
}

export function appendVersionRecord(items: VersionRecord[], input: NewVersionInput): VersionRecord[] {
  return [
    {
      id: createId("version"),
      version: input.version,
      summary: input.summary,
      impact: input.impact,
      createdAt: getNowLabel(),
    },
    ...items,
  ];
}

export function buildWorkspaceSnapshot(input: ProjectInput): WorkspaceSnapshot {
  const profile = buildProjectBlueprint(input);
  return rebuildSnapshot(profile, buildModulePlans(), buildEvidence(), buildPromptRecords(), buildVersionRecords());
}

export function refreshWorkspaceSnapshot(
  input: ProjectInput,
  modules: ModulePlan[],
  evidence: EvidenceItem[],
  prompts: PromptRecord[],
  versions: VersionRecord[],
): WorkspaceSnapshot {
  const profile = buildProjectBlueprint(input);
  return rebuildSnapshot(profile, modules, evidence, prompts, versions);
}
