import { motion } from "framer-motion";
import {
  PolarAngleAxis,
  PolarGrid,
  Radar,
  RadarChart,
  ResponsiveContainer,
} from "recharts";
import { Sparkles } from "lucide-react";
import { GlassCard } from "@/components/GlassCard";
import type { WorkspaceSnapshot } from "@/utils/workspace";

interface JudgeRadarProps {
  snapshot: WorkspaceSnapshot;
}

/**
 * 评委偏好雷达图
 * 把比赛评审的四个维度（创意 / 技术 / 完成 / 落地）映射为当前作品的可视化得分，
 * 得分基于工作台真实数据动态计算，是作品"用评审标准反向指导创作"的 meta 设计亮点。
 */
export function JudgeRadar({ snapshot }: JudgeRadarProps) {
  const totalTasks = snapshot.modules.reduce((sum, m) => sum + m.tasks.length, 0);
  const completedTasks = snapshot.modules.reduce(
    (sum, m) => sum + m.tasks.filter((t) => t.status === "已完成").length,
    0,
  );
  const taskRate = totalTasks ? completedTasks / totalTasks : 0;

  const data = [
    {
      dim: "创意创新",
      score: Math.round(82 + Math.min(snapshot.evidence.length, 8) * 2),
    },
    {
      dim: "技术应用",
      score: Math.round(75 + snapshot.prompts.length * 3 + Math.min(snapshot.versions.length * 4, 16)),
    },
    {
      dim: "完成体验",
      score: Math.round(60 + taskRate * 38),
    },
    {
      dim: "场景落地",
      score: Math.round(78 + Math.min(snapshot.documents.length * 3, 18)),
    },
  ];

  return (
    <GlassCard
      title="评委偏好映射雷达"
      eyebrow="用评审标准反向指导创作"
    >
      <div className="grid gap-5 lg:grid-cols-[0.9fr_1.1fr]">
        <div className="h-[260px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <RadarChart data={data} outerRadius="72%">
              <PolarGrid stroke="rgba(255,255,255,0.12)" />
              <PolarAngleAxis
                dataKey="dim"
                tick={{ fill: "rgba(226,232,240,0.8)", fontSize: 12, fontWeight: 500 }}
              />
              <Radar
                name="当前作品"
                dataKey="score"
                stroke="#4FD1FF"
                fill="#4FD1FF"
                fillOpacity={0.35}
                strokeWidth={2}
                isAnimationActive
                animationDuration={900}
              />
            </RadarChart>
          </ResponsiveContainer>
        </div>
        <div className="space-y-3">
          <p className="text-sm leading-6 text-slate-300">
            四个维度得分基于工作台真实数据动态计算——你每新增一条证据、推进一个任务、记录一次提示词，雷达都会实时变化。
          </p>
          {data.map((item, index) => (
            <motion.div
              key={item.dim}
              initial={{ opacity: 0, x: 16 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.15 + index * 0.1 }}
              className="flex items-center justify-between rounded-2xl border border-white/10 bg-slate-950/35 px-4 py-3"
            >
              <div className="flex items-center gap-2">
                <Sparkles className="h-3.5 w-3.5 text-cyan-300" />
                <span className="text-sm font-medium text-white">{item.dim}</span>
              </div>
              <div className="flex items-center gap-3">
                <div className="h-1.5 w-24 overflow-hidden rounded-full bg-white/10">
                  <motion.div
                    initial={{ width: 0 }}
                    animate={{ width: `${item.score}%` }}
                    transition={{ duration: 0.9, delay: 0.2 + index * 0.1, ease: "easeOut" }}
                    className="h-1.5 rounded-full bg-gradient-to-r from-cyan-300 to-emerald-300"
                  />
                </div>
                <span className="w-9 text-right text-sm font-semibold text-cyan-100">{item.score}</span>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </GlassCard>
  );
}
